+import fs from "fs";
+const files=["actions/cover-letter.js","actions/dashboard.js","actions/interview.js","actions/resume.js","lib/inngest/functions.js"];
+const pkg=JSON.parse(fs.readFileSync("package.json","utf8"));
+if(!pkg.dependencies["@google/genai"]||pkg.dependencies["@google/generative-ai"]) throw new Error("deps");
+for(const f of files){const s=fs.readFileSync(f,"utf8").split("\n").filter(l=>!l.trim().startsWith("//")).join("\n");
+ if(/generative-ai|getGenerativeModel|\.response\b|\.text\(\)/.test(s)||!s.includes("ai.models.generateContent")) throw new Error(f);}
+console.log("ok");

