new file mode 100644
index 0000000..e140d8d
--- /dev/null
+++ b/lib/gemini.js
@@ -0,0 +1,21 @@
+import { GoogleGenAI } from "@google/genai";
+
+// Gemini changelog: new paid-tier projects store generateContent requests by
+// default (store=true). These prompts carry personal career data, so opt out.
+export const GEMINI_STORE = false;
+
+const ai = new GoogleGenAI({ apiKey: process.env.GEMINI_API_KEY });
+
+// Thin adapter keeping the legacy `model.generateContent(prompt).response.text()` shape.
+export function getModel(modelName) {
+  return {
+    async generateContent(contents) {
+      const r = await ai.models.generateContent({
+        model: modelName,
+        contents,
+        config: { store: GEMINI_STORE },
+      });
+      return { response: { text: () => r.text ?? "" } };
+    },
+  };
+}
