--- /dev/null
+++ b/scripts/check-store.mjs
@@ -0,0 +1,10 @@
+import fs from "fs";
+let bad = 0;
+const files = ["actions/cover-letter.js","actions/dashboard.js","actions/interview.js","actions/resume.js","lib/inngest/functions.js"];
+for (const f of files) {
+  const s = fs.readFileSync(f,"utf8").split("\n").filter(l=>!l.trim().startsWith("//")).join("\n");
+  if (/generative-ai/.test(s) || !/getModel\(/.test(s)) { console.error("not ported:", f); bad++; }
+}
+const g = fs.existsSync("lib/gemini.js") ? fs.readFileSync("lib/gemini.js","utf8") : "";
+if (!/GEMINI_STORE = false/.test(g) || !/store: GEMINI_STORE/.test(g)) { console.error("store:false missing"); bad++; }
+process.exit(bad?1:0);
